</tr>
<tr>
<td><code v-pre>YYYY</code></td>
<td>2021</td>
<td style="text-align:right">四位数年份</td>
</tr>
<tr>
<td><code v-pre>M</code></td>
<td>1-12</td>
<td style="text-align:right">月份，从 1 开始</td>
</tr>
<tr>
<td><code v-pre>MM</code></td>
<td>01-12</td>
<td style="text-align:right">月份，两位数</td>
</tr>
<tr>
<td><code v-pre>MMM</code></td>
<td>Jan-Dec</td>
<td style="text-align:right">缩写的月份名称</td>
</tr>
<tr>
<td><code v-pre>MMMM</code></td>
<td>January-December</td>
<td style="text-align:right">完整的月份名称</td>
</tr>
<tr>
<td><code v-pre>D</code></td>
<td>1-31</td>
<td style="text-align:right">月份里的一天</td>
</tr>
<tr>
<td><code v-pre>DD</code></td>
<td>01-31</td>
<td style="text-align:right">月份里的一天，两位数</td>
</tr>
<tr>
<td><code v-pre>d</code></td>
<td>0-6</td>
<td style="text-align:right">一周中的一天，星期天是 0</td>
</tr>
<tr>
<td><code v-pre>dd</code></td>
<td>Su-Sa</td>
<td style="text-align:right">最简写的一周中一天的名称</td>
</tr>
<tr>
<td><code v-pre>ddd</code></td>
<td>Sun-Sat</td>
<td style="text-align:right">简写的一周中一天的名称</td>
</tr>
<tr>
<td><code v-pre>dddd</code></td>
<td>Sunday-Saturday</td>
<td style="text-align:right">一周中一天的名称</td>
</tr>
<tr>
<td><code v-pre>H</code></td>
<td>0-23</td>
<td style="text-align:right">小时</td>
</tr>
<tr>
<td><code v-pre>HH</code></td>
<td>00-23</td>
<td style="text-align:right">小时，两位数</td>
</tr>
<tr>
<td><code v-pre>h</code></td>
<td>1-12</td>
<td style="text-align:right">小时, 12 小时制</td>
</tr>
<tr>
<td><code v-pre>hh</code></td>
<td>01-12</td>
<td style="text-align:right">小时, 12 小时制, 两位数</td>
